require_once __DIR__.'/../includes/functions.php';admin_only();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=$pdo->prepare("SELECT * FROM internships WHERE id=?");$s->execute([$id?:0]);$r=$s->fetch();if(!$r){flash('danger','Internship not found.');redirect('manage-internships.php');}
$fields=['title','company','category','description','required_skills','responsibilities','eligibility','location','work_mode','duration','deadline'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();foreach($fields as $f)$r[$f]=trim($_POST[$f]??'');$r['stipend']=max(0,(float)($_POST['stipend']??0));$r['is_paid']=isset($_POST['is_paid'])?1:0;foreach(['title','company','category','description','location','duration','deadline'] as $f)if($r[$f]==='')$errors[]="Missing ".$f;if(!in_array($r['work_mode'],['Remote','On-site','Hybrid'],true))$errors[]='Invalid work mode';if(!$errors){$sql="UPDATE internships SET title=?,company=?,category=?,description=?,required_skills=?,responsibilities=?,eligibility=?,location=?,work_mode=?,duration=?,deadline=?,stipend=?,is_paid=? WHERE id=?";$s=$pdo->prepare($sql);$s->execute([...array_map(fn($f)=>$r[$f],$fields),$r['stipend'],$r['is_paid'],$id]);flash('success','Internship updated.');redirect('manage-internships.php');}}
$pageTitle='Edit internship';include __DIR__.'/../includes/header.php'; ?>
<h1 class="page-title">Edit internship</h1><?php foreach($errors as $er): ?><div class="alert alert-danger"><?= e($er) ?></div><?php endforeach; ?><div class="form-card"><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-3">
<?php foreach(['title'=>'Internship title','company'=>'Company','category'=>'Category','location'=>'Location','duration'=>'Duration','deadline'=>'Deadline'] as $f=>$label): ?><div class="col-md-6"><label class="form-label"><?= e($label) ?></label><input class="form-control" name="<?= e($f) ?>" value="<?= e($r[$f]) ?>" <?= $f==='deadline'?'type="date"':'' ?> required></div><?php endforeach; ?>
<div class="col-md-6"><label class="form-label">Work mode</label><select class="form-select" name="work_mode"><?php foreach(['Remote','On-site','Hybrid'] as $m): ?><option <?= $r['work_mode']===$m?'selected':'' ?>><?= e($m) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Stipend (₹/month)</label><input class="form-control" type="number" min="0" name="stipend" value="<?= e($r['stipend']) ?>"></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="is_paid" id="paid" <?= $r['is_paid']?'checked':'' ?>><label class="form-check-label" for="paid">Paid internship</label></div>
<?php foreach(['description'=>'Description','required_skills'=>'Required skills','responsibilities'=>'Responsibilities','eligibility'=>'Eligibility'] as $f=>$label): ?><div class="col-12"><label class="form-label"><?= e($label) ?></label><textarea class="form-control" rows="3" name="<?= e($f) ?>"><?= e($r[$f]) ?></textarea></div><?php endforeach; ?><div class="col-12"><button class="btn btn-primary">Update</button><a class="btn btn-outline-secondary" href="manage-internships.php">Cancel</a></div></div></form></div>
